/* @lc app=leetcode id=3665 lang=kotlin */ class Solution { fun uniquePaths(grid: Array<IntArray>): Int = grid.size.let { m -> grid[0].size.let { n -> Array(2) { IntArray(m * n) }.also { res -> (m - 1 downTo 0).forEach { r -> (n - 1 downTo 0).forEach { c -> (0..1).forEach { d -> res[d][r * n + c] = if (grid[r][c] == 0) r * n + c else if (d == 0) (if (r + 1 < m) res[1][(r + 1) * n + c] else -1) else (if (c + 1 < n) res[0][r * n + c + 1] else -1) } } } } .let { res -> IntArray(m * n).also { dp -> dp[0] = 1 }.also { dp -> (0 until m * n).forEach { x -> if (grid[x / n][x % n] == 0 && dp[x] > 0) listOf(if (x % n + 1 < n) res[0][x + 1] else -1, if (x / n + 1 < m) res[1][x + n] else -1).filter { it >= 0 }.forEach { t -> dp[t] = (dp[t] + dp[x]) % 1_000_000_007 } } }.last() } } } }